import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { addVoidReason, listVoidReasons, voidReasonsKey } from './api';

/** The sheet's void reasons and a form to add one (trimmed; a blank or repeated one refused). While the
 *  list is not empty, voiding a claim needs a reason chosen from it. */
export function VoidReasons({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const reasons = useQuery({ queryKey: voidReasonsKey(sheetId), queryFn: () => listVoidReasons(sheetId) });
  const [text, setText] = useState('');

  const save = useMutation({
    mutationFn: (input: string) => addVoidReason(sheetId, user, input),
    onSuccess: () => {
      setText('');
      return queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();

  return (
    <section>
      <h3>Void reasons</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = text;
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(input);
          });
        }}
      >
        <input data-testid="void-reason-text" placeholder="Reason" value={text}
          onChange={(e) => {
            setText(e.target.value);
            save.reset();
          }} />{' '}
        <button type="submit" data-testid="void-reason-add" disabled={save.isPending}>
          Add void reason
        </button>
        {save.isError && (
          <span data-testid="void-reason-error">A void reason needs text not already on the list.</span>
        )}
      </form>
      <ul>
        {(reasons.data ?? []).map((r) => (
          <li key={r.reason} data-testid={`void-reason-row-${r.reason}`}>
            {r.reason}
          </li>
        ))}
      </ul>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, counts, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey } from '../people/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimDue, listRates, ratesKey, sumDues } from './api';

/** Per calendar month (yyyy-mm) any claim on the sheet is dated in, the due of the claims dated in it
 *  that count (live ones only, see `liveClaims`), n/a ones skipped; earliest month first. */
export function MonthTotals({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const all = claims.data ?? [];
  const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(all, people.data).filter(counts);
  const months = [...new Set(all.map((c) => c.date.slice(0, 7)))].sort();
  const dueIn = (m: string) => sumDues(live.filter((c) => c.date.slice(0, 7) === m).map((c) => {
    const p = byId.get(c.personId);
    return p ? claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges) : null;
  }));
  return (
    <section>
      <h3>Monthly due</h3>
      <ul>
        {months.map((m) => (
          <li key={m}>{m} <span data-testid={`month-${m}-due-total`}>{dueIn(m)}</span></li>
        ))}
      </ul>
    </section>
  );
}
import { getJson, postJson } from '../../api/http';
import { counts, isBound, isCorrection, isOpen, isOverdue, type Claim } from '../claims/api';
import { sheetKey } from '../sheet/api';
import type { DatedOn } from '../settings/api';

/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
 *  (yyyy-MM-dd; null applies from the beginning of time) through its to-date (null: no end). A grade
 *  with no rate is not listed. */
export type Rate = { sheetId: string; grade: string; pct: string; from: string | null; to: string | null };
/** A blank `from` sets the rate that applies from the beginning of time; a blank `to` has no end. */
export type RateInput = { grade: string; pct: string; from: string; to: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

export const ratesKey = (sheetId: string) => [...sheetKey(sheetId), 'rates'] as const;

/** The sheet's rates, by grade, then by from-date (none first). */
export function listRates(sheetId: string): Promise<Rate[]> {
  return getJson<Rate[]>(base(sheetId));
}

/** Set a grade's rate from a from-date, replacing the one with the same grade and from-date;
 *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
 *  from-date or to-date is not a date, or the to-date is before the from-date. */
export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
 *  before it; undefined (n/a) when the date is before every rate the grade has, or it has none, or
 *  that one ended (its to-date) before the date. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found === undefined || (found.to !== null && found.to < date) ? undefined : found.pct;
}

/** The rate in force on a date for each grade that has one then. */
export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
  const byGrade = new Map<string, string>();
  for (const r of rates ?? []) {
    const pct = rateOn(rates, r.grade, date);
    if (pct !== undefined) byGrade.set(r.grade, pct);
  }
  return byGrade;
}

/** Two-decimal text (may be negative) as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const t = text.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const value = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -value : value;
}

/** A claim's rate figure: an amount times a percent, divided by 100, rounded to two decimals (half up
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date the screen shows the sheet as of ('': as it is now), from the URL (`asof`). */
function asOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

/** While the screen shows the sheet as of a date, every request about it says so: the server answers
 *  a read as the sheet stood then and refuses every change. */
function withAsOf(path: string): string {
  const date = asOf();
