import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { addVoidReason, listVoidReasons, voidReasonsKey } from './api';

/** The sheet's void reasons and a form to add one (trimmed; a blank or repeated one refused). While the
 *  list is not empty, voiding a claim needs a reason chosen from it. */
export function VoidReasons({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const reasons = useQuery({ queryKey: voidReasonsKey(sheetId), queryFn: () => listVoidReasons(sheetId) });
  const [text, setText] = useState('');

  const save = useMutation({
    mutationFn: (input: string) => addVoidReason(sheetId, user, input),
    onSuccess: () => {
      setText('');
      return queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();

  return (
    <section>
      <h3>Void reasons</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = text;
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(input);
          });
        }}
      >
        <input data-testid="void-reason-text" placeholder="Reason" value={text}
          onChange={(e) => {
            setText(e.target.value);
            save.reset();
          }} />{' '}
        <button type="submit" data-testid="void-reason-add" disabled={save.isPending}>
          Add void reason
        </button>
        {save.isError && (
          <span data-testid="void-reason-error">A void reason needs text not already on the list.</span>
        )}
      </form>
      <ul>
        {(reasons.data ?? []).map((r) => (
          <li key={r.reason} data-testid={`void-reason-row-${r.reason}`}>
            {r.reason}
          </li>
        ))}
      </ul>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, counts, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey } from '../people/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimDue, listRates, ratesKey, sumDues } from './api';

/** Per calendar month (yyyy-mm) any claim on the sheet is dated in, the due of the claims dated in it
 *  that count (live ones only, see `liveClaims`), n/a ones skipped; earliest month first. */
export function MonthTotals({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const all = claims.data ?? [];
  const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(all, people.data).filter(counts);
  const months = [...new Set(all.map((c) => c.date.slice(0, 7)))].sort();
  const dueIn = (m: string) => sumDues(live.filter((c) => c.date.slice(0, 7) === m).map((c) => {
    const p = byId.get(c.personId);
    return p ? claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges) : null;
  }));
  return (
    <section>
      <h3>Monthly due</h3>
      <ul>
        {months.map((m) => (
          <li key={m}>{m} <span data-testid={`month-${m}-due-total`}>{dueIn(m)}</span></li>
        ))}
      </ul>
    </section>
  );
}
