package net.officefloor.hq.app.asof;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.UriUtils;

/**
 * A request about a sheet carrying {@code shown-asof=<yyyy-MM-dd>} comes from a screen showing the sheet as
 * of that date. A read (any GET, and loading the sheet) is answered from the sheet as it stood then
 * ({@link AsOfStore}), with the date as its today; every change is refused (403) before anything is
 * read or written, so nothing reaches the store or the audit file.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 100)
public class AsOfFilter extends OncePerRequestFilter {

    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final AsOfStore store;

    public AsOfFilter(AsOfStore store) {
        this.store = store;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String asOf = request.getParameter("shown-asof");
        Matcher sheet = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        if (asOf == null || asOf.isBlank() || !sheet.matches()) {
            chain.doFilter(request, response);
            return;
        }
        boolean read = "GET".equals(request.getMethod())
                || ("POST".equals(request.getMethod()) && "/open".equals(sheet.group(2)));
        if (!read) {
            refuse(response, HttpStatus.FORBIDDEN, "The sheet is shown as of a date: nothing can be changed");
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(asOf.trim());
        } catch (DateTimeParseException e) {
            refuse(response, HttpStatus.BAD_REQUEST, "Not a date: " + asOf);
            return;
        }
        String schema = store.view(UriUtils.decode(sheet.group(1), StandardCharsets.UTF_8).trim(), date);
import { SheetBody } from '../../slots/defs/sheetBody';
import { ClaimedTotal } from './ClaimedTotal';
import { TagTotals } from './TagTotals';
import { VoidReasons } from './VoidReasons';

export const contributions = [
  SheetBody.fill({ order: 20, Component: ClaimedTotal }),
  SheetBody.fill({ order: 27, Component: TagTotals }),
  SheetBody.fill({ order: 9.5, Component: VoidReasons }),
];
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's content. Everything kept per sheet contributes here and is handed the active
 * sheet's id and the signed-in user; its queries go under ['sheet', sheetId, ...].
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

# A connection is pointed at another schema while a sheet is shown as of a date (asof/); the pool
# puts it back on PUBLIC when it is returned.
spring.datasource.hikari.schema=PUBLIC

